1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="My Page">
7	  <meta name="robots" content="index, follow">
8	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9	  <meta name="theme-color" content="#111214" media="(prefers-color-scheme: dark)">
10	  <meta property="og:title" content="My Page">
11	  <meta property="og:description" content="My Page">
12	  <meta property="og:type" content="website">
13	  <meta property="og:url" content="https://example.com/">
14	  <meta name="twitter:card" content="summary">
15	  <meta name="twitter:title" content="My Page">
16	  <meta name="twitter:description" content="My Page">
17	  <link rel="canonical" href="https://example.com/">
18	  <link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 16 16%22><circle cx=%228%22 cy=%228%22 r=%227%22 fill=%22%232563eb%22/></svg>">
19	  <title>My Page</title>
20	  <style>
21	    :root {
22	      color-scheme: light dark;
23	      --bg: #ffffff;
24	      --fg: #1a1a1a;
25	      --muted: #555;
26	      --accent: #2563eb;
27	      --border: #e5e7eb;
28	    }
29	
30	    @media (prefers-color-scheme: dark) {
31	      :root {
32	        --bg: #111214;
33	        --fg: #e8e8e8;
34	        --muted: #aaa;
35	        --accent: #60a5fa;
36	        --border: #2a2b2e;
37	      }
38	    }
39	
40	    * {
41	      box-sizing: border-box;
42	    }
43	
44	    html {
45	      scroll-behavior: smooth;
46	    }
47	
48	    @media (prefers-reduced-motion: reduce) {
49	      html {
50	        scroll-behavior: auto;
51	      }
52	    }
53	
54	    ::selection {
55	      background: var(--accent);
56	      color: var(--bg);
57	    }
58	
59	    body {
60	      font-family: system-ui, -apple-system, sans-serif;
61	      max-width: 40rem;
62	      margin: 3rem auto;
63	      padding: 0 1rem;
64	      line-height: 1.6;
65	      color: var(--fg);
66	      background: var(--bg);
67	    }
68	
69	    @media (max-width: 30rem) {
70	      body {
71	        margin: 1.5rem auto;
72	      }
73	    }
74	
75	    h1 {
76	      font-size: 2rem;
77	      margin-bottom: 0.5rem;
78	    }
79	
80	    p {
81	      color: var(--muted);
82	      max-width: 34rem;
83	    }
84	
85	    a {
86	      color: var(--accent);
87	      transition: opacity 0.15s ease;
88	    }
89	
90	    a:hover {
91	      opacity: 0.8;
92	    }
93	
94	    a:focus-visible,
95	    button:focus-visible {
96	      outline: 2px solid var(--accent);
97	      outline-offset: 2px;
98	    }
99	
100	    .skip-link {
101	      position: absolute;
102	      left: -9999px;
103	      top: 0;
104	      background: var(--accent);
105	      color: var(--bg);
106	      padding: 0.5rem 1rem;
107	      border-radius: 0.25rem;
108	      z-index: 10;
109	    }
110	
111	    .skip-link:focus {
112	      left: 1rem;
113	      top: 1rem;
114	    }
115	
116	    nav ul {
117	      display: flex;
118	      flex-wrap: wrap;
119	      gap: 1rem;
120	      list-style: none;
121	      padding: 0;
122	      margin: 0 0 2rem;
123	    }
124	
125	    nav a {
126	      text-decoration: none;
127	      font-weight: 500;
128	      opacity: 1;
129	    }
130	
131	    nav a:hover {
132	      text-decoration: underline;
133	    }
134	
135	    nav a[aria-current="page"] {
136	      text-decoration: underline;
137	      color: var(--fg);
138	    }
139	
140	    h2 {
141	      margin-top: 2rem;
142	      margin-bottom: 0.5rem;
143	    }
144	
145	    section + section {
146	      margin-top: 1.5rem;
147	    }
148	
149	    footer {
150	      margin-top: 3rem;
151	      padding-top: 1.5rem;
152	      border-top: 1px solid var(--border);
153	      font-size: 0.875rem;
154	      color: var(--muted);
155	    }
156	  </style>
157	</head>
158	<body>
159	  <a class="skip-link" href="#main">Skip to content</a>
160	  <nav aria-label="Primary">
161	    <ul>
162	      <li><a href="#home" data-nav-link>Home</a></li>
163	      <li><a href="#about" data-nav-link>About</a></li>
164	      <li><a href="#contact" data-nav-link>Contact</a></li>
165	    </ul>
166	  </nav>
167	  <main id="main">
168	    <section id="home" aria-labelledby="home-heading">
169	      <h1 id="home-heading">My Page</h1>
170	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
171	    </section>
172	
173	    <section id="about" aria-labelledby="about-heading">
174	      <h2 id="about-heading">About</h2>
175	      <p>Add a short description of what this page or project is about here.</p>
176	    </section>
177	
178	    <section id="contact" aria-labelledby="contact-heading">
179	      <h2 id="contact-heading">Contact</h2>
180	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
181	    </section>
182	  </main>
183	  <footer>
184	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
185	  </footer>
186	  <script>
187	    document.getElementById('year').textContent = String(new Date().getFullYear());
188	
189	    const navLinks = document.querySelectorAll('[data-nav-link]');
190	    const sections = [...navLinks].map(link => document.querySelector(link.getAttribute('href')));
191	
192	    const setActive = (id) => {
193	      navLinks.forEach(link => {
194	        if (link.getAttribute('href') === `#${id}`) {
195	          link.setAttribute('aria-current', 'page');
196	        } else {
197	          link.removeAttribute('aria-current');
198	        }
199	      });
200	    };
201	
202	    if ('IntersectionObserver' in window) {
203	      const observer = new IntersectionObserver((entries) => {
204	        const visible = entries
205	          .filter(entry => entry.isIntersecting)
206	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
207	        if (visible) setActive(visible.target.id);
208	      }, { rootMargin: '-40% 0px -50% 0px' });
209	      sections.forEach(section => section && observer.observe(section));
210	    } else {
211	      setActive(sections[0]?.id);
212	    }
213	  </script>
214	</body>
215	</html>
